// TestMenuIDConstantsMatchOfficialReport cross-checks every menu-type
// constant against the official report's "menu" registry, the same way
// the packet-id constants are pinned: a menu type sent wrong
// desynchronizes the whole window, so the ids are read rather than
// assumed. The report is generated by the vanilla server's own data
// generator and lives beside the jar; the test skips when it is absent
// so a checkout without the oracle still builds.
func TestMenuIDConstantsMatchOfficialReport(t *testing.T) {
	path := filepath.Join("..", "..", "vanilla", "reports", "registries.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("official report not available: %v", err)
	}
	var doc map[string]struct {
		Entries map[string]struct {
			ProtocolID int32 `json:"protocol_id"`
		} `json:"entries"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("parse official report: %v", err)
	}
	menu, ok := doc["minecraft:menu"]
	if !ok {
		t.Fatal("official report has no menu registry")
	}
	cases := []struct {
		name string
		got  int32
	}{
		{"generic_9x1", 0},
		{"generic_9x2", 1},
		{"generic_9x3", menuGeneric9x3},
		{"generic_3x3", menuGeneric3x3},
		{"crafter_3x3", menuCrafter3x3},
		{"anvil", menuAnvil},
		{"beacon", menuBeacon},
		{"blast_furnace", menuBlastFurnace},
		{"brewing_stand", menuBrewingStand},
		{"crafting", menuCrafting},
		{"enchantment", menuEnchantment},
		{"furnace", menuFurnace},
		{"grindstone", menuGrindstone},
		{"hopper", menuHopper},
		{"lectern", menuLectern},
		{"loom", menuLoom},
		{"shulker_box", menuShulkerBox},
		{"smithing", menuSmithing},
		{"smoker", menuSmoker},
		{"cartography_table", menuCartographyTable},
		{"stonecutter", menuStonecutter},
	}
	for _, tc := range cases {
		e, ok := menu.Entries["minecraft:"+tc.name]
		if !ok {
			t.Fatalf("menu %s missing from the official report", tc.name)
		}
		if e.ProtocolID != tc.got {
			t.Fatalf("menu %s = %d, want %d", tc.name, tc.got, e.ProtocolID)
		}
	}
}

// TestContainerMenuSpecs pins the menu type and container-side slot
// count of every generic container. The slot count is what the client's
// own menu class expects, so a wrong value desyncs the window.
func TestContainerMenuSpecs(t *testing.T) {
	cases := []struct {
		block string
		menu  int32
		slots int
	}{
		{"barrel", menuGeneric9x3, 27},
		{"dispenser", menuGeneric3x3, 9},
		{"dropper", menuGeneric3x3, 9},
		{"shulker_box", menuShulkerBox, 27},
		{"white_shulker_box", menuShulkerBox, 27},
		{"purple_shulker_box", menuShulkerBox, 27},
		{"brewing_stand", menuBrewingStand, 5},
		{"stonecutter", menuStonecutter, 2},
		{"smithing_table", menuSmithing, 4},
		{"anvil", menuAnvil, 3},
		{"chipped_anvil", menuAnvil, 3},
		{"damaged_anvil", menuAnvil, 3},
		{"enchanting_table", menuEnchantment, 2},
		{"grindstone", menuGrindstone, 3},
		{"loom", menuLoom, 4},
		{"cartography_table", menuCartographyTable, 3},
		{"lectern", menuLectern, 1},
		{"beacon", menuBeacon, 1},
		{"crafter", menuCrafter3x3, 9},
	}
	for _, tc := range cases {
		blk, ok := world.BlockState(tc.block)
		if !ok {
			t.Fatalf("unknown block %s", tc.block)
		}
		spec, ok := containerSpecFor(blk)
		if !ok {
			t.Fatalf("block %s has no container spec", tc.block)
		}
		if spec.menu != tc.menu || spec.slots != tc.slots {
			t.Fatalf("block %s: menu %d slots %d, want menu %d slots %d",
				tc.block, spec.menu, spec.slots, tc.menu, tc.slots)
		}
	}
	// Furnace-family blocks share one store but keep their own menu and
	// cook time; blasting and smoking are twice as fast as smelting,
	// which is the vanilla recipe types' own default.
	for _, tc := range []struct {
		block string
		menu  int32
		cook  int32
	}{
		{"furnace", menuFurnace, furnaceCookTicks},
		{"blast_furnace", menuBlastFurnace, blastCookTicks},
		{"smoker", menuSmoker, smokerCookTicks},
	} {
		blk, ok := world.BlockState(tc.block)
		if !ok {
			t.Fatalf("unknown block %s", tc.block)
		}
		menu, cook, _ := furnaceVariant(blk)
		if menu != tc.menu || cook != tc.cook {
			t.Fatalf("block %s: menu %d cook %d, want menu %d cook %d",
				tc.block, menu, cook, tc.menu, tc.cook)
		}
	}
	// Non-container blocks stay out of the family.
	for _, name := range []string{"stone", "chest", "hopper", "crafting_table", "furnace"} {
		blk, _ := world.BlockState(name)
		if spec, ok := containerSpecFor(blk); ok {
			t.Fatalf("block %s claimed the container spec %d", name, spec.menu)
		}
	}
}

// storedContainer reads container state straight out of the store
// without going through the block at the position.
func storedContainer(t *testing.T, s *Server, pos world.Pos) *containerData {
	t.Helper()
	d := s.dims[dimOverworld]
	d.containers.mu.Lock()
	defer d.containers.mu.Unlock()
	c := d.containers.containers[pos]
	if c == nil {
		t.Fatalf("no container state at %+v", pos)
	}
	return c
}

// containerPlace places a block and returns the live container state.
func containerPlace(t *testing.T, s *Server, block string, pos world.Pos) *containerData {
	t.Helper()
	blk, ok := world.BlockState(block)
	if !ok {
		t.Fatalf("unknown block %s", block)
	}
	s.setBlockAndBroadcast("x", pos, blk)
	c := s.containerAt(s.dims[dimOverworld], pos)
	if c == nil {
		t.Fatalf("block %s created no container", block)
	}
	return c
}

// TestContainerClickTransfer checks the pickup/place click for a
// handful of menus whose slots are typed differently, including the
// slots that refuse an item.
func TestContainerClickTransfer(t *testing.T) {
	cases := []struct {
		block   string
		item    string
		slot    int
		allowed bool
	}{
		{"barrel", "stone", 0, true},
		{"dispenser", "dirt", 8, true},
		{"shulker_box", "diamond", 26, true},
		{"crafter", "stone", 4, true},
		{"beacon", "diamond", 0, true},
		{"beacon", "stone", 0, false},
		{"enchanting_table", "lapis_lazuli", 1, true},
		{"enchanting_table", "diamond", 1, false},
		{"brewing_stand", "blaze_powder", 4, true},
		{"brewing_stand", "stone", 4, false},
		{"lectern", "written_book", 0, true},
		{"lectern", "stone", 0, false},
	}
	for _, tc := range cases {
		s := New("unused")
		sess := placeSession(t, s, "Trader", 0.5, 0.5, 0.5)
		pos := world.Pos{X: 4, Y: 4, Z: 4}
		c := containerPlace(t, s, tc.block, pos)
		sess.setStack(invSlotForHotbar(0), ItemStack{ID: world.ItemIDs[tc.item], Count: 3})

		s.openContainer(sess, pos)
		sess.windowMu.Lock()
		w := sess.window
		sess.windowMu.Unlock()
		hotbarMenu := c.spec.slots + 27
		// Pick the stack up, then place it in the container slot.
		s.handleContainerClick(sess, w, c, int16(hotbarMenu), 0, 0)
		s.handleContainerClick(sess, w, c, int16(tc.slot), 0, 0)

		got := sess.menuStack(tc.slot)
		if tc.allowed {
			if got.ID != world.ItemIDs[tc.item] || got.Count != 3 {
				t.Fatalf("%s slot %d = %+v, want the placed stack", tc.block, tc.slot, got)
			}
			if !sess.carried.Empty() {
				t.Fatalf("%s carried = %+v after a full place", tc.block, sess.carried)
			}
		} else {
			if !got.Empty() {
				t.Fatalf("%s slot %d took %+v, which it must refuse", tc.block, tc.slot, got)
			}
			if sess.carried.ID != world.ItemIDs[tc.item] || sess.carried.Count != 3 {
				t.Fatalf("%s carried = %+v after a refused place", tc.block, sess.carried)
			}
		}
	}
}

// TestContainerQuickMoveFromContainer checks that a container stack
// quick-moves into the player inventory (main rows first, like vanilla)
// for every menu.
func TestContainerQuickMoveFromContainer(t *testing.T) {
	for _, block := range []string{"barrel", "dispenser", "shulker_box", "crafter", "anvil", "loom", "stonecutter", "beacon"} {
		s := New("unused")
		sess := placeSession(t, s, "Mover", 0.5, 0.5, 0.5)
		pos := world.Pos{X: 4, Y: 4, Z: 4}
		c := containerPlace(t, s, block, pos)
		c.slots[0] = ItemStack{ID: world.ItemIDs["stone"], Count: 5}

		s.openContainer(sess, pos)
		sess.windowMu.Lock()
		w := sess.window
		sess.windowMu.Unlock()
		s.handleContainerClick(sess, w, c, 0, 0, 1)

		if !sess.menuStack(0).Empty() {
			t.Fatalf("%s slot 0 still holds %+v", block, sess.menuStack(0))
		}
		if got := sess.stackAt(slotHotbarStart + 8); got != (ItemStack{ID: world.ItemIDs["stone"], Count: 5}) {
			t.Fatalf("%s quick move landed %+v, want hotbar last slot", block, got)
		}
	}
}

// TestContainerQuickMoveIntoInputs checks the player-to-container
// direction: only the input slots fill, and a result slot never
// receives anything.
func TestContainerQuickMoveIntoInputs(t *testing.T) {
	s := New("unused")
	sess := placeSession(t, s, "Mover", 0.5, 0.5, 0.5)
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "anvil", pos)
	sess.setStack(invSlotForHotbar(0), ItemStack{ID: world.ItemIDs["stone"], Count: 2})
	sess.setStack(invSlotForHotbar(1), ItemStack{ID: world.ItemIDs["dirt"], Count: 2})

	s.openContainer(sess, pos)
	sess.windowMu.Lock()
	w := sess.window
	sess.windowMu.Unlock()
	// The first hotbar stack fills the first input, the second the other
	// input; the third has nowhere to go and stays put.
	s.handleContainerClick(sess, w, c, int16(3+27), 0, 1)
	s.handleContainerClick(sess, w, c, int16(3+28), 0, 1)
	if got := sess.menuStack(anvilLeft); got.ID != world.ItemIDs["stone"] {
		t.Fatalf("anvil left = %+v", got)
	}
	if got := sess.menuStack(anvilRight); got.ID != world.ItemIDs["dirt"] {
		t.Fatalf("anvil right = %+v", got)
	}
	sess.setStack(invSlotForHotbar(2), ItemStack{ID: world.ItemIDs["diamond"], Count: 2})
	s.handleContainerClick(sess, w, c, int16(3+29), 0, 1)
	if got := sess.menuStack(anvilResult); !got.Empty() {
		t.Fatalf("anvil result took %+v", got)
	}
	if got := sess.stackAt(invSlotForHotbar(2)); got.ID != world.ItemIDs["diamond"] || got.Count != 2 {
		t.Fatalf("third stack moved into %+v", got)
	}

	// A click straight onto the result slot neither places nor takes.
	sess.setStack(invSlotForHotbar(3), ItemStack{ID: world.ItemIDs["stone"], Count: 1})
	s.handleContainerClick(sess, w, c, int16(3+30), 0, 0)
	s.handleContainerClick(sess, w, c, anvilResult, 0, 0)
	if got := sess.menuStack(anvilResult); !got.Empty() {
		t.Fatalf("result slot = %+v after a place attempt", got)
	}
	if got := sess.carried; got.ID != world.ItemIDs["stone"] || got.Count != 1 {
		t.Fatalf("carried = %+v after a refused result click", got)
	}
}

// TestContainerQuickMoveIntoBrewing checks the brewing stand's typed
// destinations: potions to the potion slots, ingredients to the
// ingredient slot, blaze powder to the fuel slot.
func TestContainerQuickMoveIntoBrewing(t *testing.T) {
	cases := []struct {
		item string
		slot int
	}{
		{"potion", brewPotionFirst},
		{"nether_wart", brewIngredient},
		{"blaze_powder", brewFuelSlot},
	}
	for _, tc := range cases {
		s := New("unused")
		sess := placeSession(t, s, "Brewer", 0.5, 0.5, 0.5)
		pos := world.Pos{X: 4, Y: 4, Z: 4}
		c := containerPlace(t, s, "brewing_stand", pos)
		sess.setStack(invSlotForHotbar(0), ItemStack{ID: world.ItemIDs[tc.item], Count: 1})

		s.openContainer(sess, pos)
		sess.windowMu.Lock()
		w := sess.window
		sess.windowMu.Unlock()
		s.handleContainerClick(sess, w, c, int16(c.spec.slots+27), 0, 1)
		if got := sess.menuStack(tc.slot); got.ID != world.ItemIDs[tc.item] {
			t.Fatalf("%s quick move landed in %+v, want slot %d", tc.item, got, tc.slot)
		}
	}
}

// TestBrewingStandBrews walks the vanilla brew cycle: blaze powder tops
// the fuel up to twenty charges, starting a brew costs one charge and
// sets the property to 400, and the ingredient is consumed when the
// countdown reaches zero.
func TestBrewingStandBrews(t *testing.T) {
	s := New("unused")
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "brewing_stand", pos)
	c.slots[brewPotionFirst] = ItemStack{ID: world.ItemIDs["potion"], Count: 1}
	c.slots[brewIngredient] = ItemStack{ID: world.ItemIDs["nether_wart"], Count: 2}
	c.slots[brewFuelSlot] = ItemStack{ID: world.ItemIDs["blaze_powder"], Count: 2}

	s.containerTickStep()
	if c.fuel != brewingFuelPerPowder-1 {
		t.Fatalf("fuel after starting a brew = %d, want %d", c.fuel, brewingFuelPerPowder-1)
	}
	if c.brewTime != brewingStandTicks {
		t.Fatalf("brew time = %d, want %d", c.brewTime, brewingStandTicks)
	}
	if got := c.slots[brewFuelSlot].Count; got != 1 {
		t.Fatalf("blaze powder = %d, want one consumed", got)
	}
	for i := 0; i < brewingStandTicks; i++ {
		s.containerTickStep()
	}
	if c.brewTime != 0 {
		t.Fatalf("brew time after the countdown = %d", c.brewTime)
	}
	if got := c.slots[brewIngredient]; got.Count != 1 || got.ID != world.ItemIDs["nether_wart"] {
		t.Fatalf("ingredient after the brew = %+v, want one nether wart left", got)
	}
	// The potions are still there: turning an ingredient into a specific
	// potion needs the potion contents component, which is a TODO.
	if got := c.slots[brewPotionFirst]; got.ID != world.ItemIDs["potion"] {
		t.Fatalf("potion slot = %+v", got)
	}
	// The second powder is untouched until the fuel runs out again.
	if got := c.slots[brewFuelSlot].Count; got != 1 {
		t.Fatalf("blaze powder = %d after one brew", got)
	}
	if c.fuel != brewingFuelPerPowder-1 {
		t.Fatalf("fuel = %d after one brew", c.fuel)
	}
}

// TestBrewingStandAbortsOnIngredientSwap checks that swapping the
// ingredient mid-brew resets the countdown, as vanilla does.
func TestBrewingStandAbortsOnIngredientSwap(t *testing.T) {
	s := New("unused")
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "brewing_stand", pos)
	c.slots[brewPotionFirst] = ItemStack{ID: world.ItemIDs["potion"], Count: 1}
	c.slots[brewIngredient] = ItemStack{ID: world.ItemIDs["nether_wart"], Count: 1}
	c.slots[brewFuelSlot] = ItemStack{ID: world.ItemIDs["blaze_powder"], Count: 1}

	s.containerTickStep()
	if c.brewTime == 0 {
		t.Fatal("brew never started")
	}
	c.slots[brewIngredient] = ItemStack{ID: world.ItemIDs["redstone"], Count: 1}
	s.containerTickStep()
	if c.brewTime != 0 {
		t.Fatalf("brew time = %d after the ingredient changed", c.brewTime)
	}
	if got := c.slots[brewIngredient]; got.Count != 1 {
		t.Fatalf("ingredient = %+v after the aborted brew", got)
	}
}

// TestBrewingStandOpenPackets proves the wire shape: menu type 11, 41
// menu slots, and the two progress properties.
func TestBrewingStandOpenPackets(t *testing.T) {
	s := New("unused")
	c, pr, _ := joinPlay(t, s, "Brewer")
	defer c.Close()
	drainJoinBurst(t, pr)
	drainToQuiet(t, pr)

	sess := s.findSessionByName("Brewer")
	pos := world.Pos{X: 8, Y: -61, Z: 0}
	stand, _ := world.BlockState("brewing_stand")
	s.setBlockAndBroadcast("Brewer", pos, stand)
	drainToQuiet(t, pr)

	s.openContainer(sess, pos)
	os, err := waitPacket(t, pr, IDPlayOpenScreen)
	if err != nil {
		t.Fatal(err)
	}
	r := protocol.NewPacketReader(os.Data)
	if _, err := r.VarInt(); err != nil { // window
		t.Fatal(err)
	}
	if typ, err := r.VarInt(); err != nil || typ != menuBrewingStand {
		t.Fatalf("menu type = %d, err %v (want %d)", typ, err, menuBrewingStand)
	}
	cc, err := waitPacket(t, pr, IDPlayContainerContent)
	if err != nil {
		t.Fatal(err)
	}
	cr := protocol.NewPacketReader(cc.Data)
	_, _ = cr.VarInt()
	_, _ = cr.VarInt()
	if n, err := cr.VarInt(); err != nil || n != 5+36 {
		t.Fatalf("brewing slots = %d, err %v (want %d)", n, err, 41)
	}
	for i := 0; i < 2; i++ {
		p, err := waitPacket(t, pr, IDPlayContainerProperty)
		if err != nil {
			t.Fatal(err)
		}
		pr := protocol.NewPacketReader(p.Data)
		if _, err := pr.VarInt(); err != nil {
			t.Fatal(err)
		}
		prop, err := pr.Short()
		if err != nil || prop != int16(i) {
			t.Fatalf("property %d = %d, err %v", i, prop, err)
		}
	}
}

