// TestContainerClickPacketRoutes proves a Click Container packet for a
// generic window reaches its menu handler.
func TestContainerClickPacketRoutes(t *testing.T) {
	s := New("unused")
	sess := placeSession(t, s, "Clicker", 0.5, 0.5, 0.5)
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "barrel", pos)
	sess.setStack(invSlotForHotbar(0), ItemStack{ID: world.ItemIDs["stone"], Count: 2})

	s.openContainer(sess, pos)
	sess.windowMu.Lock()
	w := sess.window
	sess.windowMu.Unlock()
	s.handleClickContainer(sess, clickWindowPacket(t, sess, w.id, int16(c.spec.slots+27), 0, 0))
	s.handleClickContainer(sess, clickWindowPacket(t, sess, w.id, 0, 0, 0))
	if got := c.slots[0]; got != (ItemStack{ID: world.ItemIDs["stone"], Count: 2}) {
		t.Fatalf("barrel slot = %+v", got)
	}
	if !sess.carried.Empty() {
		t.Fatalf("carried = %+v", sess.carried)
	}
}

// TestContainerContentsDroppedOnBreak proves a broken container spills
// what it held.
func TestContainerContentsDroppedOnBreak(t *testing.T) {
	s := New("unused")
	_ = placeSession(t, s, "Breaker", 0.5, 0.5, 0.5)
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "barrel", pos)
	c.slots[0] = ItemStack{ID: world.ItemIDs["stone"], Count: 3}
	c.slots[20] = ItemStack{ID: world.ItemIDs["diamond"], Count: 1}

	s.setBlockAndBroadcast("Breaker", pos, world.Air)
	var dropped []ItemStack
	s.entities.mu.RLock()
	for _, e := range s.entities.byID {
		if e.Item.ID != 0 {
			dropped = append(dropped, e.Item)
		}
	}
	s.entities.mu.RUnlock()
	if len(dropped) != 2 {
		t.Fatalf("drops = %+v, want two stacks", dropped)
	}
	seen := map[int32]int32{}
	for _, d := range dropped {
		seen[d.ID] = d.Count
	}
	if seen[world.ItemIDs["stone"]] != 3 || seen[world.ItemIDs["diamond"]] != 1 {
		t.Fatalf("drops = %+v", seen)
	}
	if _, ok := s.dims[dimOverworld].containers.containers[pos]; ok {
		t.Fatal("container state outlived the block")
	}
}

// TestShulkerBoxKeepsContentsOnBreak proves a broken box leaves exactly
// one item behind — the box itself — with its contents attached, which
// is what lets a full box be moved without spilling.
func TestShulkerBoxKeepsContentsOnBreak(t *testing.T) {
	s := New("unused")
	_ = placeSession(t, s, "Breaker", 0.5, 0.5, 0.5)
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "white_shulker_box", pos)
	c.slots[3] = ItemStack{ID: world.ItemIDs["diamond"], Count: 7}

	s.setBlockAndBroadcast("Breaker", pos, world.Air)
	var dropped []ItemStack
	s.entities.mu.RLock()
	for _, e := range s.entities.byID {
		if e.Item.ID != 0 {
			dropped = append(dropped, e.Item)
		}
	}
	s.entities.mu.RUnlock()
	if len(dropped) != 1 {
		t.Fatalf("drops = %+v, want only the box", dropped)
	}
	box := dropped[0]
	if box.ID != world.ItemIDs["white_shulker_box"] || box.Count != 1 {
		t.Fatalf("drop = %+v, want the white shulker box item", box)
	}
	if box.Contents == nil {
		t.Fatal("the box item lost its contents")
	}
	if got := box.Contents[3]; got != (ItemStack{ID: world.ItemIDs["diamond"], Count: 7}) {
		t.Fatalf("stored slot = %+v", got)
	}
}

// TestShulkerBoxContentsSurvivePickupAndPlace walks the round trip: the
// dropped box is picked up with its contents, and placing it again puts
// them back in the block entity.
func TestShulkerBoxContentsSurvivePickupAndPlace(t *testing.T) {
	s := New("unused")
	sess := placeSession(t, s, "Mover", 8.5, -60, 8.5)
	from := world.Pos{X: 8, Y: -62, Z: 8}
	c := containerPlace(t, s, "orange_shulker_box", from)
	c.slots[0] = ItemStack{ID: world.ItemIDs["stone"], Count: 12}
	s.setBlockAndBroadcast("Mover", from, world.Air)

	var box ItemStack
	s.entities.mu.RLock()
	for _, e := range s.entities.byID {
		if e.Item.ID == world.ItemIDs["orange_shulker_box"] {
			box = e.Item
		}
	}
	s.entities.mu.RUnlock()
	if box.Contents == nil {
		t.Fatal("broken box carried no contents")
	}
	remainder, picked := sess.addStack(box)
	if !picked || !remainder.Empty() {
		t.Fatalf("pickup = %+v, picked %v", remainder, picked)
	}
	if got := sess.stackAt(slotHotbarStart); got.Contents == nil {
		t.Fatalf("hotbar stack = %+v, contents lost on pickup", got)
	}

	// Placing the box back through the use-item path re-creates the
	// block entity with what the item carried. The player stands in the
	// world, so the target is the block beside them.
	to := world.Pos{X: 8, Y: -60, Z: 8}
	stone, _ := world.BlockState("stone")
	s.setBlockAndBroadcast("Mover", world.Pos{X: to.X, Y: to.Y - 1, Z: to.Z}, stone)
	sess.held.Store(0)
	s.handleUseItem(sess, useItemPkt(0, int32(to.X), int32(to.Y-1), int32(to.Z), 1, nil))
	c2 := s.containerAt(s.dims[dimOverworld], to)
	if c2 == nil {
		t.Fatal("placed box created no block entity")
	}
	if got := c2.slots[0]; got != (ItemStack{ID: world.ItemIDs["stone"], Count: 12}) {
		t.Fatalf("replaced box slot = %+v", got)
	}
	if c2.spec.menu != menuShulkerBox {
		t.Fatalf("placed box menu = %d", c2.spec.menu)
	}
}

// TestContainerPersistenceRoundTrip saves and reloads every generic
// container's state, including the brewing stand's in-flight brew.
func TestContainerPersistenceRoundTrip(t *testing.T) {
	path := filepath.Join(t.TempDir(), "data.json")
	s := New("unused")
	s.DataPath = path

	barrelPos := world.Pos{X: 4, Y: 5, Z: 6}
	barrel := containerPlace(t, s, "barrel", barrelPos)
	barrel.slots[7] = ItemStack{ID: world.ItemIDs["stone"], Count: 9}

	brewPos := world.Pos{X: 8, Y: 5, Z: 6}
	brew := containerPlace(t, s, "brewing_stand", brewPos)
	brew.slots[brewIngredient] = ItemStack{ID: world.ItemIDs["nether_wart"], Count: 4}
	brew.brewTime = 123
	brew.fuel = 17

	boxPos := world.Pos{X: 12, Y: 5, Z: 6}
	box := containerPlace(t, s, "cyan_shulker_box", boxPos)
	box.slots[1] = ItemStack{ID: world.ItemIDs["diamond"], Count: 2}

	if err := s.SaveServerData(); err != nil {
		t.Fatal(err)
	}

	s2 := New("unused")
	s2.DataPath = path
	if err := s2.LoadServerData(); err != nil {
		t.Fatal(err)
	}
	// The reloaded state is read straight out of the store: the blocks
	// themselves come from world generation, so a loaded container must
	// stand on its own until a chunk is loaded over it.
	if got := storedContainer(t, s2, barrelPos).slots[7]; got != (ItemStack{ID: world.ItemIDs["stone"], Count: 9}) {
		t.Fatalf("restored barrel = %+v", got)
	}
	got := storedContainer(t, s2, brewPos)
	if got.spec.menu != menuBrewingStand || got.brewTime != 123 || got.fuel != 17 {
		t.Fatalf("restored brewing stand = menu %d brew %d fuel %d", got.spec.menu, got.brewTime, got.fuel)
	}
	if got.slots[brewIngredient].Count != 4 {
		t.Fatalf("restored ingredient = %+v", got.slots[brewIngredient])
	}
	restored := storedContainer(t, s2, boxPos)
	if restored.block != "cyan_shulker_box" || restored.spec.menu != menuShulkerBox {
		t.Fatalf("restored box = %q menu %d", restored.block, restored.spec.menu)
	}
	if got := restored.slots[1]; got != (ItemStack{ID: world.ItemIDs["diamond"], Count: 2}) {
		t.Fatalf("restored box slot = %+v", got)
	}
}

// TestBlastFurnaceAndSmokerSmelt checks that the two faster furnace
// family members share the smelting tick with their own cook time.
func TestBlastFurnaceAndSmokerSmelt(t *testing.T) {
	cases := []struct {
		block  string
		menu   int32
		input  string
		output string
	}{
		{"blast_furnace", menuBlastFurnace, "raw_iron", "iron_ingot"},
		{"smoker", menuSmoker, "beef", "cooked_beef"},
		{"furnace", menuFurnace, "raw_iron", "iron_ingot"},
	}
	for _, tc := range cases {
		s := New("unused")
		pos := world.Pos{X: 4, Y: 4, Z: 4}
		blk, _ := world.BlockState(tc.block)
		s.setBlockAndBroadcast("x", pos, blk)
		f := s.furnaceAt(s.dims[dimOverworld], pos)
		if f.kind != tc.menu {
			t.Fatalf("%s menu = %d, want %d", tc.block, f.kind, tc.menu)
		}
		f.slots[furnaceInput] = ItemStack{ID: world.ItemIDs[tc.input], Count: 1}
		f.slots[furnaceFuel] = ItemStack{ID: world.ItemIDs["coal"], Count: 1}

		for i := int32(0); i < f.cookTicks; i++ {
			s.furnaceTickStep()
		}
		s.dims[dimOverworld].furnaces.mu.Lock()
		got := f.slots[furnaceOutput]
		s.dims[dimOverworld].furnaces.mu.Unlock()
		if got != (ItemStack{ID: world.ItemIDs[tc.output], Count: 1}) {
			t.Fatalf("%s output = %+v after %d ticks, want %s", tc.block, got, f.cookTicks, tc.output)
		}
	}
}

