// TestCrafterSlotToggleStored proves the crafter's per-slot lock
// toggles are recorded for the window on screen.
func TestCrafterSlotToggleStored(t *testing.T) {
	s := New("unused")
	sess := placeSession(t, s, "Crafter", 0.5, 0.5, 0.5)
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	c := containerPlace(t, s, "crafter", pos)

	s.openContainer(sess, pos)
	sess.windowMu.Lock()
	w := sess.window
	sess.windowMu.Unlock()
	// A disabled slot is a set bit; re-enabling clears it again.
	for _, tc := range []struct {
		slot    int32
		enabled bool
		want    uint16
	}{
		{2, false, 1 << 2},
		{5, false, 1<<2 | 1<<5},
		{2, true, 1 << 5},
	} {
		var b protocol.Buffer
		b.VarInt(tc.slot)
		b.VarInt(w.id)
		b.Bool(tc.enabled)
		s.handleContainerSlotStateChanged(sess, protocol.Packet{ID: IDPlayContainerSlotStateChangedSB, Data: b.Bytes()})
		s.dims[dimOverworld].containers.mu.Lock()
		got := c.disabled
		s.dims[dimOverworld].containers.mu.Unlock()
		if got != tc.want {
			t.Fatalf("disabled = %b after toggling slot %d to %v, want %b", got, tc.slot, tc.enabled, tc.want)
		}
	}
}

// TestContainerRenameAndBeaconSelection proves the anvil rename lands
// as the open menu's pending name and the beacon's effect choice is
// stored on the open menu.
func TestContainerRenameAndBeaconSelection(t *testing.T) {
	s := New("unused")
	sess := placeSession(t, s, "Nam er", 0.5, 0.5, 0.5)

	anvilPos := world.Pos{X: 4, Y: 4, Z: 4}
	containerPlace(t, s, "anvil", anvilPos)
	s.openContainer(sess, anvilPos)
	var rb protocol.Buffer
	rb.String("Excalibur")
	s.handleRenameItem(sess, protocol.Packet{ID: IDPlayRenameItemSB, Data: rb.Bytes()})
	sess.windowMu.Lock()
	name := sess.window.pendingName
	sess.windowMu.Unlock()
	if name != "Excalibur" {
		t.Fatalf("anvil rename = %q", name)
	}

	beaconPos := world.Pos{X: 8, Y: 4, Z: 4}
	beacon := containerPlace(t, s, "beacon", beaconPos)
	s.openContainer(sess, beaconPos)
	// The effect ids are prefixed optionals: a presence flag, then the
	// id when present.
	var bb protocol.Buffer
	bb.Bool(true)
	bb.VarInt(1)
	bb.Bool(false)
	s.handleSetBeacon(sess, protocol.Packet{ID: IDPlaySetBeaconSB, Data: bb.Bytes()})
	s.dims[dimOverworld].containers.mu.Lock()
	primary, hasPrimary := beacon.beaconPrimary, beacon.hasBeaconPrimary
	s.dims[dimOverworld].containers.mu.Unlock()
	if !hasPrimary || primary != 1 {
		t.Fatalf("beacon primary = %d, set %v", primary, hasPrimary)
	}
}

// TestContainerBlockSwapResetsStorage proves a container replaced by a
// different container family drops what it held instead of carrying a
// slot layout the new menu cannot show.
func TestContainerBlockSwapResetsStorage(t *testing.T) {
	s := New("unused")
	pos := world.Pos{X: 4, Y: 4, Z: 4}
	barrel := containerPlace(t, s, "barrel", pos)
	barrel.slots[0] = ItemStack{ID: world.ItemIDs["stone"], Count: 4}

	dispenser, _ := world.BlockState("dispenser")
	s.setBlockAndBroadcast("x", pos, dispenser)
	got := s.containerAt(s.dims[dimOverworld], pos)
	if got.spec.slots != 9 || got.spec.menu != menuGeneric3x3 {
		t.Fatalf("swapped container = menu %d slots %d", got.spec.menu, got.spec.slots)
	}
	if !got.slots[0].Empty() {
		t.Fatalf("swapped container kept %+v", got.slots[0])
	}
	dropped := false
	s.entities.mu.RLock()
	for _, e := range s.entities.byID {
		if e.Item.ID == world.ItemIDs["stone"] && e.Item.Count == 4 {
			dropped = true
		}
	}
	s.entities.mu.RUnlock()
	if !dropped {
		t.Fatal("the replaced barrel's contents were not dropped")
	}
}
